import { forwardRef, useCallback } from 'react';
import {
  Animated,
  Pressable,
  StyleSheet,
  type PressableProps,
  type StyleProp,
  type View,
  type ViewStyle,
} from 'react-native';
import { useGlassTheme } from './glass-provider';
import {
  CheckText,
  CheckWell,
  checkFieldStyles,
  useDrawIn,
  usePressDown,
  type CheckSize,
} from './lib/check-field';
import { GlassIcon, type GlassIconName } from './lib/icons';
import { useControllableState } from './lib/use-controllable-state';

export type GlassCheckboxSize = CheckSize;

export type GlassCheckedState = boolean | 'indeterminate';

export type GlassCheckboxProps = Omit<PressableProps, 'children' | 'onPress' | 'style'> & {
  checked?: GlassCheckedState;
  defaultChecked?: GlassCheckedState;
  /** A line of muted text under the label. */
  description?: string;
  /** Marks the choice as wrong: the box's edge turns the invalid colour. */
  invalid?: boolean;
  /** Text beside the box; the whole row then toggles it. Without one, set accessibilityLabel. */
  label?: string;
  /** Hears the new state. Pressing an indeterminate box checks it. */
  onCheckedChange?: (checked: boolean) => void;
  size?: GlassCheckboxSize;
  style?: StyleProp<ViewStyle>;
};

const BOX = {
  sm: { radius: 5, size: 16 },
  md: { radius: 7, size: 20 },
} as const;

// The web's 2.1 stroke on a 16-point grid, redrawn on GlassIcon's 20-point grid.
const MARK_STROKE = 2.1 * (20 / 16);

type MarkProps = {
  name: GlassIconName;
  progress: Animated.Value;
  size: number;
};

// A mark grows in from half size as it fades in, and shrinks back as it fades out.
function Mark({ name, progress, size }: MarkProps) {
  const { colors } = useGlassTheme();

  return (
    <Animated.View
      style={[
        StyleSheet.absoluteFill,
        styles.centre,
        {
          opacity: progress.interpolate({
            extrapolate: 'clamp',
            inputRange: [0, 1],
            outputRange: [0, 1],
          }),
          transform: [
            { scale: progress.interpolate({ inputRange: [0, 1], outputRange: [0.5, 1] }) },
          ],
        },
      ]}
    >
      <GlassIcon
        color={colors.accentForeground}
        name={name}
        size={size * 0.84}
        strokeWidth={MARK_STROKE}
      />
    </Animated.View>
  );
}

/**
 * A checkbox for one choice or, with `checked="indeterminate"`, for a parent of several. The box
 * fills with the accent and its mark draws in; unchecking runs the same way back.
 */
export const GlassCheckbox = forwardRef<View, GlassCheckboxProps>(
  (
    {
      checked,
      defaultChecked = false,
      description,
      disabled,
      invalid = false,
      label,
      onCheckedChange,
      onPressIn,
      onPressOut,
      size = 'md',
      style,
      ...rest
    },
    ref,
  ) => {
    const { preferences } = useGlassTheme();
    const [state, setState] = useControllableState<GlassCheckedState>(checked, defaultChecked);
    const tick = useDrawIn(state === true, preferences.reduceMotion);
    const dash = useDrawIn(state === 'indeterminate', preferences.reduceMotion);
    const press = usePressDown(preferences.reduceMotion, onPressIn, onPressOut);
    const box = BOX[size];

    // A lone box still answers a 44-point touch.
    const hitSlop = label === undefined ? (44 - box.size) / 2 : undefined;

    // An indeterminate box becomes checked, as on the web.
    const toggle = useCallback(() => {
      const next = state !== true;

      setState(next);
      onCheckedChange?.(next);
    }, [onCheckedChange, setState, state]);

    return (
      <Pressable
        ref={ref}
        accessibilityHint={description}
        accessibilityLabel={label}
        accessibilityRole="checkbox"
        accessibilityState={{
          checked: state === 'indeterminate' ? 'mixed' : state,
          disabled: Boolean(disabled),
        }}
        disabled={disabled}
        hitSlop={hitSlop}
        onPress={toggle}
        onPressIn={press.handlePressIn}
        onPressOut={press.handlePressOut}
        style={[
          label === undefined ? checkFieldStyles.alone : checkFieldStyles.field,
          label !== undefined && size === 'sm' && checkFieldStyles.fieldSmall,
          disabled && checkFieldStyles.disabled,
          style,
        ]}
        {...rest}
      >
        <CheckWell
          chosen={state !== false}
          invalid={invalid}
          press={press.press}
          radius={box.radius}
          size={box.size}
        >
          <Mark name="check" progress={tick} size={box.size} />
          <Mark name="dash" progress={dash} size={box.size} />
        </CheckWell>
        {label === undefined ? null : (
          <CheckText description={description} label={label} size={size} />
        )}
      </Pressable>
    );
  },
);

GlassCheckbox.displayName = 'GlassCheckbox';

const styles = StyleSheet.create({
  centre: { alignItems: 'center', justifyContent: 'center' },
});

import { useCallback, useEffect, useState, type ReactNode } from 'react';
import {
  Animated,
  Easing,
  StyleSheet,
  Text,
  View,
  type GestureResponderEvent,
  type PressableProps,
} from 'react-native';
import { useGlassTheme } from '../glass-provider';
import { GLASS_MOTION } from './tokens';

export type CheckSize = 'sm' | 'md';

// The edge of an empty box is what says it can be ticked, so it holds 3:1 over the glass it
// sits on, which a text field's hairline does not.
const EDGE = { dark: 'rgba(244, 245, 249, 0.78)', light: 'rgba(27, 29, 36, 0.6)' } as const;

const EDGE_WIDTH = 1.5;

// The recessed well a field sits in, from --lg-input-shadow.
const WELL_SHADOW = {
  dark: 'inset 0px 1px 2px rgba(0, 0, 0, 0.24), inset 0px -1px 0px rgba(255, 255, 255, 0.06)',
  light: 'inset 0px 1px 2px rgba(0, 0, 0, 0.08), inset 0px -1px 0px rgba(255, 255, 255, 0.8)',
} as const;

// A chosen box is a bead of the accent, lit along its top.
const CHOSEN_SHADOW =
  'inset 0px 1px 0px rgba(255, 255, 255, 0.4), inset 0px -1px 0px rgba(0, 0, 0, 0.14), 0px 1px 3px rgba(0, 0, 0, 0.28)';

/**
 * Runs from 0 to 1 as `on` turns true, springing in, and back to 0, quicker and without the
 * spring, as it turns false. Reduce Motion jumps to the end.
 */
export function useDrawIn(on: boolean, reduceMotion: boolean) {
  const [progress] = useState(() => new Animated.Value(on ? 1 : 0));

  useEffect(() => {
    if (reduceMotion) {
      progress.setValue(on ? 1 : 0);

      return;
    }

    if (on) {
      Animated.spring(progress, {
        ...GLASS_MOTION.spring,
        toValue: 1,
        useNativeDriver: GLASS_MOTION.nativeDriver,
      }).start();

      return;
    }

    Animated.timing(progress, {
      duration: 140,
      easing: Easing.in(Easing.quad),
      toValue: 0,
      useNativeDriver: GLASS_MOTION.nativeDriver,
    }).start();
  }, [on, progress, reduceMotion]);

  return progress;
}

/** A press that sets a box down and springs it back. Reduce Motion leaves the box still. */
export function usePressDown(
  reduceMotion: boolean,
  onPressIn: PressableProps['onPressIn'],
  onPressOut: PressableProps['onPressOut'],
) {
  const [press] = useState(() => new Animated.Value(0));

  const settle = useCallback(
    (toValue: number) => {
      if (reduceMotion) return;

      Animated.spring(press, {
        ...GLASS_MOTION.spring,
        toValue,
        useNativeDriver: GLASS_MOTION.nativeDriver,
      }).start();
    },
    [press, reduceMotion],
  );

  const handlePressIn = useCallback(
    (event: GestureResponderEvent) => {
      onPressIn?.(event);
      settle(1);
    },
    [onPressIn, settle],
  );

  const handlePressOut = useCallback(
    (event: GestureResponderEvent) => {
      onPressOut?.(event);
      settle(0);
    },
    [onPressOut, settle],
  );

  return { handlePressIn, handlePressOut, press };
}

type CheckWellProps = {
  /** The mark, centred over the box. */
  children: ReactNode;
  /** Filled with the accent: a checked or indeterminate box, or the chosen radio. */
  chosen: boolean;
  invalid: boolean;
  /** The press progress from usePressDown. */
  press: Animated.Value;
  radius: number;
  size: number;
};

/**
 * The small recessed well a checkbox or radio draws. It fills with the accent when chosen and
 * sets down to 90% under a press.
 */
export function CheckWell({ children, chosen, invalid, press, radius, size }: CheckWellProps) {
  const { colors, preferences } = useGlassTheme();
  const fill = useDrawIn(chosen, preferences.reduceMotion);
  const corners = { borderCurve: 'continuous', borderRadius: radius } as const;

  return (
    <Animated.View
      style={[
        corners,
        {
          backgroundColor: colors.controlSurface,
          borderColor: invalid ? colors.invalid : EDGE[preferences.theme],
          borderWidth: EDGE_WIDTH,
          boxShadow: WELL_SHADOW[preferences.theme],
          height: size,
          width: size,
          transform: [
            {
              scale: preferences.reduceMotion
                ? 1
                : press.interpolate({ inputRange: [0, 1], outputRange: [1, 0.9] }),
            },
          ],
        },
      ]}
    >
      <Animated.View
        style={[
          styles.cover,
          corners,
          {
            backgroundColor: colors.accent,
            boxShadow: CHOSEN_SHADOW,
            opacity: fill.interpolate({
              extrapolate: 'clamp',
              inputRange: [0, 1],
              outputRange: [0, 1],
            }),
          },
        ]}
      />
      <View style={[styles.cover, styles.centre]}>{children}</View>
    </Animated.View>
  );
}

type CheckTextProps = {
  description?: string;
  label: string;
  size: CheckSize;
};

/** The label beside a checkbox or radio, with an optional muted line under it. */
export function CheckText({ description, label, size }: CheckTextProps) {
  const { colors } = useGlassTheme();

  return (
    <View style={styles.text}>
      <Text
        style={[size === 'sm' ? styles.labelSmall : styles.label, { color: colors.foreground }]}
      >
        {label}
      </Text>
      {description ? (
        <Text style={[styles.description, { color: colors.mutedForeground }]}>{description}</Text>
      ) : null}
    </View>
  );
}

export const checkFieldStyles = StyleSheet.create({
  alone: { alignSelf: 'flex-start' },
  disabled: { opacity: 0.45 },
  // A labelled row is one touch target, at least 44 points tall.
  field: {
    alignItems: 'flex-start',
    flexDirection: 'row',
    gap: 12,
    minHeight: 44,
    paddingVertical: 11,
  },
  fieldSmall: { gap: 10 },
});

const styles = StyleSheet.create({
  centre: { alignItems: 'center', justifyContent: 'center' },
  // Covers the edge as well, so a chosen box shows no rim.
  cover: {
    bottom: -EDGE_WIDTH,
    left: -EDGE_WIDTH,
    position: 'absolute',
    right: -EDGE_WIDTH,
    top: -EDGE_WIDTH,
  },
  description: { fontSize: 13, lineHeight: 18 },
  label: { fontSize: 15, lineHeight: 21 },
  labelSmall: { fontSize: 14, lineHeight: 20 },
  text: { flex: 1, minWidth: 0, paddingTop: 1 },
});

import { View } from 'react-native';
import Svg, { Path } from 'react-native-svg';

export type GlassIconName =
  | 'check'
  | 'chevron-down'
  | 'chevron-right'
  | 'close'
  | 'dash'
  | 'danger'
  | 'info'
  | 'success'
  | 'warning';

// The web components' own strokes, drawn on a 20-point grid.
const PATHS = {
  check: ['M4.5 10.5 8.25 14.25 15.5 6.25'],
  'chevron-down': ['M5 7.5l5 5 5-5'],
  'chevron-right': ['M7.5 4.4 13.1 10l-5.6 5.6'],
  close: ['M5.5 5.5l9 9m0-9l-9 9'],
  dash: ['M5 10h10'],
  danger: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M7.6 7.6l4.8 4.8', 'M12.4 7.6l-4.8 4.8'],
  info: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M10 9.2v4.1', 'M10 6.7h.01'],
  success: ['M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Z', 'M6.9 10.2l2.2 2.2 4-4.4'],
  warning: ['M10 3.6 17 16H3L10 3.6Z', 'M10 8.4v3.4', 'M10 14h.01'],
} as const satisfies Record<GlassIconName, readonly string[]>;

export type GlassIconProps = {
  color: string;
  name: GlassIconName;
  size?: number;
  strokeWidth?: number;
};

/** A stroked glyph from the library's small icon set. Decorative; label its control instead. */
export function GlassIcon({ color, name, size = 20, strokeWidth = 1.8 }: GlassIconProps) {
  // The hiding lives on a View: on the web, Svg passes its props to a bare <svg> element.
  return (
    <View
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      style={{ height: size, width: size }}
    >
      <Svg width={size} height={size} viewBox="0 0 20 20" fill="none">
        {PATHS[name].map((path) => (
          <Path
            key={path}
            d={path}
            stroke={color}
            strokeLinecap="round"
            strokeLinejoin="round"
            strokeWidth={strokeWidth}
          />
        ))}
      </Svg>
    </View>
  );
}
